// 세션정보를 얻기위한 함수사용

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        if (js_market === "1" || js_market === "2" || js_market === "6") {
            $c.cm.setColumnProp(grd_List_2, "LD_MKT_TP_NM", "Show", false);
            panel_mkt_gubun.hide();
        } else {
            panel_mkt_gubun.show("");
        }

        // 초기화
        $c.cm.setColumnProp(grd_List_2, "ISU_CD", "Show", false);
        $c.cm.setColumnProp(grd_List_2, "ISU_KOR_NM", "Show", false);
        const vHeadString = "QRY_ID:STRING(100),BZ_NM:STRING(300),CNT:STRING(20)";
        // dts_List_1.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        $c.cm.PanelToGroupBox(panel_Top);
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05934.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05934.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadError
 * @description dts_List_1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05934.dts_List_1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_2_OnLoadError
 * @description dts_List_2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List_2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05934.dts_List_2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Cnt_OnLoadError
 * @description dts_Cnt 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Cnt_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Cnt);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05934.dts_Cnt_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_2_OnLoadCompleted
 * @description dts_List_2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page_2);
        if (rowcount > 0) {
            scwin.gridList2Change('ISUR_CD');
            scwin.gridList2Change('COM_NM');
            scwin.gridList2Change('ISU_CD');
            scwin.gridList2Change('ISU_KOR_NM');
        } else {
            scwin.gridList2Init();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05934.dts_List_2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_1_OnClick
 * @description grd_List_1 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_1_OnClick = function(row, colid) {
    try {
        scwin.readSync(row, colid);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05934.grd_List_1_OnClick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05934.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05934.btn_SDate_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name gridAddRow
 * @description grid Add Row 처리
 * @param {String} pQryId pQryId
 * @param {String} pBzNm pBzNm
 * @param {*} pCnt pCnt
 * @returns {void}
 * @hidden N
 */
scwin.gridAddRow = function(pQryId, pBzNm, pCnt) {
    dts_List_1.insertRow();
    dts_List_1.setCellData(dts_List_1.getRowCount(), "QRY_ID", pQryId);
    dts_List_1.setCellData(dts_List_1.getRowCount(), "BZ_NM", pBzNm);
    dts_List_1.setCellData(dts_List_1.getRowCount(), "CNT", pCnt);
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    // var vBzNm  ="회사신규상장";
    // fn_gridAddRow(vBzNm, fn_count_read_sync('100'));
    dts_List_1.removeAll();
    let gTotalCnt = 0;
    const arrPar = new Array();
    arrPar[0] = {
        BZ_NM: '회사신규상장',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.corp.newlist"
    };
    arrPar[1] = {
        BZ_NM: '종목신규상장',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.isu.newlist"
    };
    arrPar[2] = {
        BZ_NM: '회사상장폐지',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.corp.delist"
    };
    arrPar[3] = {
        BZ_NM: '종목상장폐지',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.isu.delist"
    };
    arrPar[4] = {
        BZ_NM: '관리종목지정',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.admisu"
    };
    arrPar[5] = {
        BZ_NM: '매매거래정지',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.haltisu"
    };
    arrPar[6] = {
        BZ_NM: '주식발행',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.isu.isslist"
    };
    arrPar[7] = {
        BZ_NM: '상호변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.comnm.change"
    };
    arrPar[8] = {
        BZ_NM: '종목명변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.isunm.change"
    };
    arrPar[9] = {
        BZ_NM: '결산기변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.fiscal.change"
    };
    arrPar[10] = {
        BZ_NM: '업종변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.ind.change"
    };
    arrPar[11] = {
        BZ_NM: '소속부변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.sect.change"
    };
    arrPar[12] = {
        BZ_NM: '대표이사변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.ceo.change"
    };
    arrPar[13] = {
        BZ_NM: '본점소재지변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.addr.change"
    };
    arrPar[14] = {
        BZ_NM: '법인기타정보변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.corpetc.change"
    };
    grd_List_1.Redraw = false;
    let gCnt = 0;
    for (let i = 0; i < arrPar.length; i++) {
        gCnt = scwin.countReadSync(arrPar[i].BZ_NM, arrPar[i].QRY_ID);
        scwin.gridAddRow(arrPar[i].QRY_ID, arrPar[i].BZ_NM, gCnt);
        gTotalCnt += gCnt;
    }
    grd_List_1.Redraw = true;
    $c.stf.fillGridHeaderTotalCnt(gTotalCnt, panel_page_1);

    // dts_List_2 초기화
    dts_List_2.removeAll();
    $c.stf.fillGridHeaderTotalCnt(0, panel_page_2);
};

/**
 * @method
 * @name getMktTpCd
 * @description get Mkt Tp Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.getMktTpCd = function() {
    let vMarketTpCd = "";
    if (js_market === "1" || js_market === "2" || js_market === "6") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = rdo_MARKET_TP_CD.getValue();
    }
    return vMarketTpCd;
};

/**
 * @method
 * @name countReadSync
 * @description count Read Sync 처리
 * @param {String} pBzNm pBzNm
 * @param {String} pQryId pQryId
 * @returns {void}
 * @hidden N
 */
scwin.countReadSync = function(pBzNm, pQryId) {
    dts_Cnt.DataID = encodeURI(scwin.qryUrl(pBzNm, pQryId));
    dts_Cnt.reset();
    return dts_Cnt.getRowCount();
};

/**
 * @method
 * @name readSync
 * @description 그리드 더블클릭시
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.readSync = function(row, colid) {
    dts_List_2.DataID = encodeURI(scwin.qryUrl(dts_List_1.getCellData(row, 'BZ_NM'), dts_List_1.getCellData(row, 'QRY_ID')));
    dts_List_2.reset();
};

/**
 * @method
 * @name qryUrl
 * @description qry Url 처리
 * @param {String} pBzNm pBzNm
 * @param {String} pQryId pQryId
 * @returns {void}
 * @hidden N
 */
scwin.qryUrl = function(pBzNm, pQryId) {
    let url = "";
    url = "/listingCommon.do?SCREN_ID=" + "ULDSTF05934.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=" + pQryId;
    if (pBzNm === '관리종목지정') {
        url += "&outputMessageId=LISTING_BZ_PROCS_LIST_OUT_MAISU";
    } else {
        url += "&outputMessageId=LISTING_BZ_PROCS_LIST_OUT";
    }
    if (pBzNm === '대표이사변경' || pBzNm === '본점소재지변경') {
        url += "&{P}param01=" + edt_SDate.getValue();
        url += "&{P}param02=" + scwin.getMktTpCd(); // 시장구분
        url += "&{P}param03=" + scwin.getMktTpCd(); // 시장구분

    } else if (pBzNm === '종목명변경' || pBzNm === '관리종목지정') {
        url += "&{P}param01=" + scwin.getMktTpCd(); // 시장구분
        url += "&{P}param02=" + scwin.getMktTpCd(); // 시장구분
        url += "&{P}param03=" + edt_SDate.getValue();
        url += "&{P}param04=" + scwin.getMktTpCd(); // 시장구분
        url += "&{P}param05=" + scwin.getMktTpCd(); // 시장구분
        url += "&{P}param06=" + edt_SDate.getValue();
    } else {
        url += "&{P}param01=" + scwin.getMktTpCd(); // 시장구분
        url += "&{P}param02=" + scwin.getMktTpCd(); // 시장구분
        url += "&{P}param03=" + edt_SDate.getValue();
    }
    return url;
};

/**
 * @method
 * @name gridList2Change
 * @description grid List2 Change 처리
 * @param {String} pId pId
 * @returns {void}
 * @hidden N
 */
scwin.gridList2Change = function(pId) {
    if (dts_List_2.getCellData(1, pId) === "") {
        $c.cm.setColumnProp(grd_List_2, pId, "Show", false);
    } else {
        $c.cm.setColumnProp(grd_List_2, pId, "Show", true);
    }
};

/**
 * @method
 * @name gridList2Init
 * @description grid List2 Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.gridList2Init = function() {
    $c.cm.setColumnProp(grd_List_2, "ISUR_CD", "Show", true);
    $c.cm.setColumnProp(grd_List_2, "COM_NM", "Show", true);
    $c.cm.setColumnProp(grd_List_2, "ISU_CD", "Show", false);
    $c.cm.setColumnProp(grd_List_2, "ISU_KOR_NM", "Show", false);
};
